'use strict';
(()=>{const stage=document.querySelector('#game-stage');if(!stage)return;const de=document.documentElement.lang==='de',E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let DB,round=[],index=0,score=0,answered=false,mode='myth';
const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
function scoreboard(){return '<div class="quiz-score" id="round-score"><strong>'+(de?score+' / 5 Punkte':score+' / 5 points')+'</strong><span>'+(de?index+' von 5 Fragen beantwortet':index+' of 5 questions answered')+'</span><progress max="5" value="'+index+'" aria-label="'+(de?'Beantwortete Fragen':'Questions answered')+'">'+index+'/5</progress></div>'}
function stop(){const full=index===5;const message=index===0?(de?'Noch ungespielt – die nächste Runde wartet auf Sie.':'No answers yet: the next round is waiting for you.'):score===index?(de?'Alle beantworteten Fragen geknackt – stark!':'Every question you tried, cracked. Nicely done!'):score>=3?(de?'Gut kombiniert! Ein paar kleine Git-Fallen waren dabei.':'Good detective work! There were a few Git traps along the way.'):(de?'Ein paar knifflige Fälle dabei? Genau dafür gibt es die Erklärungen.':'A few tricky ones? That’s what the explanations are for.');stage.innerHTML='<h2>'+(full?(de?'Runde geschafft!':'Round complete!'):(de?'Ihr Zwischenstand':'Your score so far'))+'</h2>'+scoreboard()+'<p>'+message+'</p><p>'+(de?'Ein Punkt pro richtiger Antwort. Lust auf eine neue Runde? Oder nehmen Sie sich das gesammelte Wissen mit.':'One point for every correct answer. Fancy another round? Or take the complete reading edition with you.')+'</p><div class="actions"><button class="button" id="game-replay">'+(de?'Noch eine Runde!':'Another round!')+'</button><a href="/'+(de?'de/git-verstehen/wissen-kompakt/':'en/understanding-git/compact-knowledge/')+'">'+(de?'Alle Themen lesen und herunterladen →':'Read and download all topics →')+'</a></div>';document.querySelector('#game-replay').onclick=()=>start(mode)}
function show(){if(index>=round.length){stop();return}answered=false;const n=round[index],x=mode==='myth'?(de?n:n.en):n,title=mode==='myth'?(x.claim||x.title):x.title;let choices=mode==='myth'?[{text:de?'Fakt':'Fact',good:n.kind==='F'},{text:de?'Mythos':'Myth',good:n.kind==='M'}]:shuffle([{text:n.good,good:true},{text:n.bad,good:false}]);stage.innerHTML=scoreboard()+'<p class="eyebrow">'+(de?'Frage ':'Question ')+(index+1)+' / 5 · '+(de?'freiwillige Runde':'optional round')+'</p><h2>'+E(title)+'</h2>'+(mode==='antipattern'?'<p>'+E(n.problem)+'</p><p>'+(de?'Welche Vorgehensweise empfehlen wir?':'Which approach do we recommend?')+'</p>':'')+'<div class="answers">'+choices.map((c,i)=>'<button type="button" data-game-answer="'+i+'">'+E(c.text)+'</button>').join('')+'</div><div id="game-feedback" role="status"></div><div class="actions"><button class="button" id="game-next" hidden>'+(de?'Nächste Frage →':'Next question →')+'</button><button type="button" id="game-stop">'+(de?'Runde hier beenden':'End the round here')+'</button></div>';stage.querySelectorAll('[data-game-answer]').forEach(b=>b.onclick=()=>{if(answered)return;answered=true;const c=choices[+b.dataset.gameAnswer];if(c.good)score++;index++;stage.querySelectorAll('[data-game-answer]').forEach((a,i)=>{a.disabled=true;a.classList.toggle('answer-correct',choices[i].good);a.classList.toggle('answer-wrong',a===b&&!c.good)});const detail=mode==='myth'?(x.detail||[x.surprise,x.utility,x.limits].filter(Boolean).join(' ')):n.good+' '+n.boundary;document.querySelector('#game-feedback').innerHTML='<p><strong>'+(c.good?(de?['Volltreffer! +1 Punkt','Gut kombiniert! +1 Punkt','Die Git-Falle erkannt! +1 Punkt'][(index-1)%3]:['Bullseye! +1 point','Nicely reasoned! +1 point','Git trap spotted! +1 point'][(index-1)%3]):(de?'Knifflig! Diesmal kein Punkt – aber hier kommt die Auflösung:':'Tricky! No point this time, but here’s the explanation:'))+'</strong></p><p>'+E(detail)+'</p>';document.querySelector('#round-score').outerHTML=scoreboard();document.querySelector('#game-next').hidden=false;document.querySelector('#game-next').textContent=index===5?(de?'Zum Rundenergebnis →':'See your result →'):(de?'Nächste Frage →':'Next question →')});document.querySelector('#game-next').onclick=show;document.querySelector('#game-stop').onclick=stop}
function start(which){mode=which;index=0;score=0;round=shuffle(mode==='myth'?DB.nodes:DB.academy[de?'de':'en'].cards).slice(0,5);show()}
fetch('/assets/data.json').then(r=>r.json()).then(db=>{DB=db.knowledge;document.querySelector('#game-start').onclick=()=>start('myth');document.querySelector('#game-antipattern').onclick=()=>start('antipattern');window.GITGAME={ready:true}}).catch(()=>{stage.textContent=de?'Das Spiel konnte nicht geladen werden. Alle Themen bleiben in der Wissensfassung verfügbar.':'The game could not be loaded. All topics remain available in the reading edition.'});})();
